    });

    it("uses last bracket cost when no overflow cost specified", () => {
      const noOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ]);
      expect(noOverflow.computeShippingCents([line("a", 3000)], 1000)).toBe(700);
    });

    it("sums weight across multiple lines", () => {
      // 300 * 2 + 400 * 1 = 1000 → second bracket (upToGrams: 2000)
      const lines = [line("a", 300, 2), line("b", 400, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(700);
    });

    it("sorts brackets internally regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 500, costCents: 300 },
      ]);
      expect(unordered.computeShippingCents([line("a", 400)], 1000)).toBe(300);
      expect(unordered.computeShippingCents([line("a", 1000)], 1000)).toBe(700);
    });
  });
});

