  });

  describe("updateQuantity", () => {
    it("updates quantity of an existing product", () => {
      const cart = new Cart();
      cart.add(productA, 3);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity set to 0", () => {
      const cart = new Cart();
      cart.add(productA, 3);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
      expect(cart.snapshot()).toHaveLength(0);
    });

    it("throws for non-existent product", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("missing", 5)).toThrow("Product missing is not in the cart");
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("empties the cart", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      cart.add(productB, 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
      expect(cart.snapshot()).toHaveLength(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy that does not affect cart internals", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const snap = cart.snapshot();
      snap[0]!.quantity = 999;
      snap[0]!.product.unitPriceCents = 1;
      expect(cart.itemCount).toBe(2);
      expect(cart.snapshot()[0]!.product.unitPriceCents).toBe(1000);
    });
  });

  describe("totals — pricing pipeline", () => {
    it("computes correct totals with no discount, no tax, free shipping", () => {
      const cart = new Cart();
      cart.add(productA, 2); // 2 * 1000 = 2000
      cart.add(productB, 1); // 1 * 2000 = 2000
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(4000);
      expect(totals.discountCents).toBe(0);
      expect(totals.taxCents).toBe(0);
      expect(totals.shippingCents).toBe(0);
      expect(totals.totalCents).toBe(4000);
    });

    it("applies discount, then tax on discounted subtotal, then shipping", () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const mockTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(350),
      };
      const mockShipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(200),
      };

      const cart = new Cart({
        discountPolicy: mockDiscount,
        taxCalculator: mockTax,
        shippingCalculator: mockShipping,
        region: "US-CA",
      });
      cart.add(productA, 5); // subtotal = 5000

      const totals = cart.totals();

      // discount clamped: max(0, 500) = 500, min(500, 5000) = 500
      expect(totals.subtotalCents).toBe(5000);
      expect(totals.discountCents).toBe(500);
      // tax called with discounted subtotal (5000 - 500 = 4500) and region
      expect(mockTax.computeTaxCents).toHaveBeenCalledWith(4500, "US-CA");
      expect(totals.taxCents).toBe(350);
      // shipping called with lines and discounted subtotal
      expect(mockShipping.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        4500,
      );
      expect(totals.shippingCents).toBe(200);
      // total = discounted subtotal + tax + shipping
      expect(totals.totalCents).toBe(4500 + 350 + 200);
    });

    it("clamps discount to 0 when policy returns negative", () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ discountPolicy: mockDiscount });
      cart.add(productA, 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(0);
    });

    it("clamps discount to subtotal when policy returns more", () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(99999),
      };
      const cart = new Cart({ discountPolicy: mockDiscount });
      cart.add(productA, 1); // subtotal = 1000
      const totals = cart.totals();
      expect(totals.discountCents).toBe(1000);
      expect(totals.totalCents).toBe(0); // fully discounted, no tax/shipping on 0
    });

    it("clamps negative tax to 0", () => {
      const mockTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-50),
      };
      const cart = new Cart({ taxCalculator: mockTax });
      cart.add(productA, 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const mockShipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-50),
      };
      const cart = new Cart({ shippingCalculator: mockShipping });
      cart.add(productA, 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("empty cart produces all-zero totals", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("defaults region to US", () => {
      const mockTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator: mockTax });
      cart.add(productA, 1);
      cart.totals();
      expect(mockTax.computeTaxCents).toHaveBeenCalledWith(1000, "US");
    });
  });

  describe("checkout", () => {
    it("returns totals and lines for a basic checkout", async () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0]!.quantity).toBe(2);
    });

    it("refreshes prices via priceFetcher before computing totals", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const result = await cart.checkout({ priceFetcher });
      expect(result.totals.subtotalCents).toBe(1500); // refreshed
      expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
    });

    it("validates inventory and passes when available", async () => {
      const cart = new Cart();
      cart.add(productA, 2);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(productA, 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
          reason: "low stock",
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(5);
        expect(invErr.available).toBe(2);
        expect(invErr.message).toBe("low stock");
      }
    });

    it("throws InventoryError on partial-stock denial (available < requested)", async () => {
      const cart = new Cart();
      cart.add(productA, 10);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(10);
        expect(invErr.available).toBe(3);
      }
    });

    it("generates default message when reason is not provided", async () => {
      const cart = new Cart();
      cart.add(productA, 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false }),
      };

      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
        /insufficient stock for a/,
      );
    });

    it("uses asyncTaxProvider when provided", async () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const mockShipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };

      const cart = new Cart({
        discountPolicy: mockDiscount,
        shippingCalculator: mockShipping,
        region: "US-CA",
      });
      cart.add(productA, 3); // subtotal = 3000

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.10),
      };

      const result = await cart.checkout({ asyncTaxProvider });

      // subtotal=3000, discount=200, discounted=2800, tax=280 (10%), shipping=500
      expect(result.totals.subtotalCents).toBe(3000);
      expect(result.totals.discountCents).toBe(200);
      expect(result.totals.taxCents).toBe(280);
      expect(result.totals.shippingCents).toBe(500);
      expect(result.totals.totalCents).toBe(2800 + 280 + 500);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("propagates asyncTaxProvider failure", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service down");
    });

    it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(100),
      };

      const cart = new Cart({ discountPolicy: mockDiscount, region: "FR" });
      cart.add(productA, 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1200),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.20),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // Refreshed subtotal = 1200 * 2 = 2400
      // discount = 100, discounted = 2300
      // tax = floor(2300 * 0.20) = 460
      expect(result.totals.subtotalCents).toBe(2400);
      expect(result.totals.discountCents).toBe(100);
      expect(result.totals.taxCents).toBe(460);
      expect(result.totals.totalCents).toBe(2300 + 460);

      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("FR");
    });

    it("first denied line wins when multiple items are in cart", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 1);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn()
          .mockResolvedValueOnce({ available: true })
          .mockResolvedValueOnce({ available: false, reason: "discontinued" }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        expect((err as InventoryError).productId).toBe("b");
        expect((err as InventoryError).message).toBe("discontinued");
      }
    });

    it("checkout does not mutate internal cart state", async () => {
      const cart = new Cart();
      cart.add(productA, 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(9999),
      };
      await cart.checkout({ priceFetcher });

      // Internal cart still has original price
      expect(cart.totals().subtotalCents).toBe(2000);
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [999999, 0],
    [-500, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "percent must be between 0 and 100"],
      [101, "percent must be between 0 and 100"],
      [NaN, "percent must be between 0 and 100"],
      [Infinity, "percent must be between 0 and 100"],
    ])("rejects out-of-range percent %s", (percent, msg) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
    });

    it("accepts boundary values 0 and 100", () => {
      expect(() => new PercentageDiscountPolicy(0)).not.toThrow();
      expect(() => new PercentageDiscountPolicy(100)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it.each([
      [10, 1000, 100],
      [50, 1000, 500],
      [100, 1000, 1000],
      [0, 1000, 0],
      [33, 100, 33],
      [10, 999, 99],    // floors: 999 * 10 / 100 = 99.9 → 99
      [15, 333, 49],    // floors: 333 * 15 / 100 = 49.95 → 49
    ])("%i%% of %i cents = %i", (percent, subtotal, expected) => {
      const policy = new PercentageDiscountPolicy(percent);
      expect(policy.computeDiscountCents(subtotal)).toBe(expected);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amounts", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amounts", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it.each([
      [500, 1000, 500],  // discount < subtotal
      [500, 300, 300],   // discount > subtotal: capped to subtotal
      [500, 500, 500],   // discount = subtotal
      [0, 1000, 0],      // zero discount
    ])("discount=%i, subtotal=%i → %i", (amount, subtotal, expected) => {
      const policy = new FixedAmountDiscountPolicy(amount);
      expect(policy.computeDiscountCents(subtotal)).toBe(expected);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all policies using original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10),   // 100
          new FixedAmountDiscountPolicy(200), // 200
        ],
        "sum",
      );
      // 10% of 1000 = 100, fixed 200 → total 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("can exceed subtotal (clamping is caller's job)", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(80),   // 800
          new FixedAmountDiscountPolicy(500), // 500
        ],
        "sum",
      );
      // 80% of 1000 = 800, fixed min(500,1000)=500 → 1300 (exceeds 1000)
      expect(composite.computeDiscountCents(1000)).toBe(1300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative child results to 0 before summing", () => {
      const negativePolicy = {
        computeDiscountCents: () => -50,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      // -50 clamped to 0, plus min(100, 1000) = 100
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10),   // 10% of 1000 = 100
          new FixedAmountDiscountPolicy(200), // min(200, 900) = 200
        ],
        "chain",
      );
      // total discount = 100 + 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("ordering matters in chain mode", () => {
      const policiesA = [
        new FixedAmountDiscountPolicy(200), // 200 off 1000 → remaining 800
        new PercentageDiscountPolicy(10),   // 10% of 800 = 80
      ];
      const policiesB = [
        new PercentageDiscountPolicy(10),   // 10% of 1000 = 100 → remaining 900
        new FixedAmountDiscountPolicy(200), // min(200, 900) = 200
      ];

      const compA = new CompositeDiscountPolicy(policiesA, "chain");
      const compB = new CompositeDiscountPolicy(policiesB, "chain");

      expect(compA.computeDiscountCents(1000)).toBe(280); // 200 + 80
      expect(compB.computeDiscountCents(1000)).toBe(300); // 100 + 200
    });

    it("cannot exceed subtotal in chain mode", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(600),
          new FixedAmountDiscountPolicy(600),
        ],
        "chain",
      );
      // first: min(600, 1000)=600, remaining=400
      // second: min(600, 400)=400, remaining=0
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("defaults to sum mode when mode omitted", () => {
      const composite = new CompositeDiscountPolicy([
        new FixedAmountDiscountPolicy(100),
        new FixedAmountDiscountPolicy(200),
      ]);
      // sum: 100 + 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
